# ── shapes ────────────────────────────────────────────────────────────

def person(name: str, address: str) -> dict:
    return {"emailAddress": {"name": name, "address": address}}


ME = person(OWNER_NAME, OWNER_EMAIL)


def addr_of(name: str, domain: str = "example.edu") -> str:
    return name.lower().replace(" ", ".") + "@" + domain


def entry(eid: str, etype: str, description: str, *, from_email: str = "",
          from_name: str = "", conv: str = "", msg: str = "",
          gmail_thread: str = "", date: str = "2030-03-02T15:00:00Z",
          deadline: str = "", notes: str = "", last_action: str = "",
          priority: str = "", **extra) -> dict:
    row = {"id": eid, "type": etype, "description": description,
           "from_email": from_email, "from_name": from_name,
           "conversation_id": conv, "source_message_id": msg,
           "gmail_thread_id": gmail_thread, "date_identified": date,
           "deadline": deadline, "notes": notes, "last_action": last_action,
           "priority": priority, "status": "open"}
    row.update(extra)
    return row


def sent(conv: str, subject: str, ts: str, *, to=(), cc=(), preview: str = "") -> dict:
    msg = {"conversationId": conv, "subject": subject, "sentDateTime": ts,
           "bodyPreview": preview, "from": ME}
    if to or cc:
        msg["toRecipients"] = [person(n, a) for n, a in to]
        msg["ccRecipients"] = [person(n, a) for n, a in cc]
    return msg


def inbound(conv: str, subject: str, ts: str, frm: tuple, preview: str = "") -> dict:
    return {"conversationId": conv, "subject": subject, "bodyPreview": preview,
            "from": person(*frm), "receivedDateTime": ts}


def event(subject: str, start: str, *, attendees=(), organizer=None) -> dict:
    org = organizer or (OWNER_NAME, OWNER_EMAIL)
    return {"subject": subject,
            "start": {"dateTime": start, "timeZone": "UTC"},
            "isAllDay": False, "showAs": "busy",
            "organizer": person(*org),
            "attendees": [person(n, a) for n, a in attendees]}


def world(**kw) -> dict:
    w = {"sent": [], "inbox": [], "events": [], "closed_conversations": {}}
    w.update(kw)
    return w


def rfc2822(iso: str) -> str:
    return format_datetime(datetime.fromisoformat(iso.replace("Z", "+00:00")))


def case(case_id: str, label: str, cohort: str, linkage: str, signal,
         rationale: str, row: dict, w: dict, *, as_of: str = "",
         notes_topup=()) -> dict:
    return {"case_id": case_id, "label": label, "cohort": cohort,
            "linkage": linkage, "signal_under_test": signal,
            "provenance": "synthetic: tests/fixtures/closure_corpus_synthetic.py",
            "world_fidelity": "synthetic", "notes_topup": list(notes_topup),
            "rationale": rationale,
            "as_of": as_of or "2030-03-30T10:00:00Z",
            "entry": row, "world": w}


