def outlook_reply_cases() -> list[dict]:
    out = []
    for i, subject in enumerate(REPLY_SUBJECTS):
        n = i + 1
        who = PEOPLE[i]
        addr = addr_of(who, "example.org" if i % 3 == 0 else "example.edu")
        conv, msg = f"conv-syn-r{n:03d}", f"msg-syn-r{n:03d}"
        day = 1 + (i % 20)
        created = f"2030-03-{day:02d}T14:00:00Z"
        replied = f"2030-03-{day + 1:02d}T16:30:00Z"
        if i < 16:
            etype, eid, closes_on = "response_needed", f"response-syn-r{n:03d}", ""
            desc = f"Needs response: {subject}"
            why = ("a detector row; the user's reply in its conversation is "
                   "the deliverable, so it closes with no click.")
        else:
            etype, prefix, closes_on, tier = NON_DETECTOR[i - 16]
            eid = f"{prefix}-r{n:03d}"
            desc = f"{subject} ({who})"
            why = ("a reply row by type or by closes_on=reply; the reply closes it."
                   if tier == "decisive" else
                   f"a {etype} row: a reply in its thread proposes the close, "
                   "since the reply may be about something else.")
        extra = {"closes_on": closes_on} if closes_on else {}
        row = entry(eid, etype, desc, from_email=addr, from_name="", conv=conv,
                    msg=msg, date=created,
                    notes=f"{who.split()[0]} wrote about: {subject.lower()}.",
                    **extra)
        to = [(who, addr)] if i % 2 == 0 else ()
        w = world(sent=[sent(conv, f"RE: {subject}", replied, to=to,
                             preview="Thanks, that works for me.")])
        out.append(case(f"tp-user_replied_outlook-r{n:03d}", "should_close",
                        "user_replied_outlook_true_positive", "email_linked",
                        "user_replied_outlook", why, row, w))
    return out


